reference_solution:
def count_target_majority_subarrays(nums,target):
    answer=0
    for left in range(len(nums)):
        count=0
        for right in range(left,len(nums)):
            count+=nums[right]==target
            if count*2>right-left+1:answer+=1
    return answer

